    }

    @Override
    public Page<Tag> list(int offset, int limit) {
        List<Tag> items = entityManager.createQuery("select e from Tag e order by e.id", Tag.class)
                .setFirstResult(offset)
                .setMaxResults(limit)
                .getResultList();
        long total = entityManager.createQuery("select count(e) from Tag e", Long.class).getSingleResult();
        return new Page<>(items, total, offset, limit);
    }

    @Override
    public Tag insert(Tag entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Tag", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public Tag update(Tag entity) {
        Tag[] stored = new Tag[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Tag", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(Tag entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Tag", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
            transaction.commit();
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

