            }
        }
        {
            Object value = values.get("price");
            if (value == null) {
                if (creating || values.containsKey("price")) errors.add(new FieldError("price", "is required"));
            } else {
                if (!(number(value).compareTo(new BigDecimal("0")) >= 0)) errors.add(new FieldError("price", "must be >= 0"));
            }
        }
        {
            Object value = values.get("status");
            if (value == null) {
                if (creating || values.containsKey("status")) errors.add(new FieldError("status", "is required"));
            } else {
                if (value instanceof String text && text.length() > 10) errors.add(new FieldError("status", "is longer than 10 characters"));
            }
        }
        {
            Object value = values.get("version");
            if (value == null) {
                if (!creating && values.containsKey("version")) errors.add(new FieldError("version", "cannot be empty"));
            }
        }
        {
            Long categoryId = (Long) (values.containsKey("categoryId") ? values.get("categoryId") : current == null ? null : current.getCategoryId());
            if (categoryId != null && uow.categories().findById(categoryId).isEmpty())
                errors.add(new FieldError("category_id", "no Category has this key"));
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Product", errors);
    }

    /** A number of any type, to compare it. */
    private static BigDecimal number(Object value) {
        return new BigDecimal(String.valueOf(value));
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Product current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Product entity, Map<String, Object> values) {
        if (values.containsKey("categoryId")) entity.setCategoryId((Long) values.get("categoryId"));
        if (values.containsKey("name")) entity.setName((String) values.get("name"));
        if (values.containsKey("price")) entity.setPrice((BigDecimal) values.get("price"));
        if (values.containsKey("status")) entity.setStatus((String) values.get("status"));
        if (values.containsKey("version")) entity.setVersion((Integer) values.get("version"));
        if (values.containsKey("deletedAt")) entity.setDeletedAt((OffsetDateTime) values.get("deletedAt"));
    }

    /** The Product with this key; NotFoundException when there is none. */
    private Product find(UnitOfWork uow, Long id) {
        return uow.products().findById(id).orElseThrow(() -> new NotFoundException("Product", id));
    }

    /** The Product as services return it. */
    private static ProductRead read(Product entity) {
        return new ProductRead(entity.getId(), entity.getCategoryId(), entity.getName(), entity.getPrice(), entity.getStatus(), entity.getVersion(), entity.getDeletedAt());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(ProductUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.categoryId() != null && changes.categoryId().isPresent()) values.put("categoryId", changes.categoryId().value());
        if (changes.name() != null && changes.name().isPresent()) values.put("name", changes.name().value());
        if (changes.price() != null && changes.price().isPresent()) values.put("price", changes.price().value());
        if (changes.status() != null && changes.status().isPresent()) values.put("status", changes.status().value());
        if (changes.version() != null && changes.version().isPresent()) values.put("version", changes.version().value());
        if (changes.deletedAt() != null && changes.deletedAt().isPresent()) values.put("deletedAt", changes.deletedAt().value());
        return values;
    }

    /** Stores a new Product after checking it. */
    public ProductRead createProduct(ProductCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.categoryId() != null) values.put("categoryId", data.categoryId());
        if (data.name() != null) values.put("name", data.name());
        if (data.price() != null) values.put("price", data.price());
        if (data.status() != null) values.put("status", data.status());
        if (data.version() != null) values.put("version", data.version());
        if (data.deletedAt() != null) values.put("deletedAt", data.deletedAt());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Product entity = new Product();
            apply(entity, values);
            return read(uow.products().insert(entity));
        });
    }

    /** The Product with this key; NotFoundException when there is none. */
    public ProductRead getProduct(Long id) {
        return read(find(uow, id));
    }

    /** A page of products, by primary key. */
    public Page<ProductRead> listProducts(int offset, int limit) {
        return uow.products().list(offset, limit).map(ProductService::read);
    }

    /** Changes the given values of a Product, read at version. */
    public ProductRead updateProduct(Long id, ProductUpdate changes, Integer version) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Product current = find(uow, id);
            if (!Objects.equals(current.getVersion(), version))
                throw new ConflictException("Product", "was changed by someone else since it was read", List.of("version"));
            check(uow, values, current);
            apply(current, values);
            current.setVersion(version + 1);
            return read(uow.products().update(current));
        });
    }

    /** Marks a Product as deleted (deleted_at); reads leave it out from then on. */
    public void deleteProduct(Long id, Integer version) {
        uow.transaction((uow) -> {
            Product current = find(uow, id);
            if (!Objects.equals(current.getVersion(), version))
                throw new ConflictException("Product", "was changed by someone else since it was read", List.of("version"));
            if (!uow.orderLines().listByProductId(current.getId()).isEmpty()) throw new ConflictException("Product", "rows of order_lines still point to it", List.of("order_lines"));
            current.setDeletedAt(OffsetDateTime.now(ZoneOffset.UTC));
            uow.products().update(current);
            return null;
        });
    }

    /** The products with this category_id. */
    public List<ProductRead> listProductsByCategoryId(Long categoryId) {
        return uow.products().listByCategoryId(categoryId).stream().map(ProductService::read).toList();
    }

    /** Links a Product and a Tag (product_tags). */
    public void addTag(Long productId, Long tagId) {
        uow.transaction((uow) -> {
            find(uow, productId);
            if (uow.tags().findById(tagId).isEmpty()) throw new NotFoundException("Tag", tagId);
            if (uow.productTags().findByProductIdAndTagId(productId, tagId).isPresent()) throw new ConflictException("Product", "is already linked to this Tag", List.of("tagId"));
            ProductTag link = new ProductTag();
            link.setProductId(productId);
            link.setTagId(tagId);
            uow.productTags().insert(link);
            return null;
        });
    }

    /** Removes the link between a Product and a Tag (product_tags). */
    public void removeTag(Long productId, Long tagId) {
        uow.transaction((uow) -> {
            ProductTag link = uow.productTags().findByProductIdAndTagId(productId, tagId).orElseThrow(() -> new NotFoundException("ProductTag", List.of(productId, tagId)));
            uow.productTags().delete(link);
            return null;
        });
    }
}

